def split_keep_delimiters(s, delims):
    delim_set = set(delims)
    tokens = []
    current = []
    for c in s:
        if c in delim_set:
            if current:
                tokens.append("".join(current))
                current = []
            tokens.append(c)
        else:
            current.append(c)
    if current:
        tokens.append("".join(current))
    return tokens

def chunk_string(s, n):
    if not s:
        return []
    return [s[i:i + n] for i in range(0, len(s), n)]

def split_into_sentences(s):
    sentences = []
    current = []
    for c in s:
        if c in '.!?':
            sentence = "".join(current).strip()
            if sentence:
                sentences.append(sentence)
            current = []
        else:
            current.append(c)
    tail = "".join(current).strip()
    if tail:
        sentences.append(tail)
    return sentences

def group_consecutive_same_case(s):
    letters = [c for c in s if c.isalpha()]
    if not letters:
        return []
    groups = []
    current = letters[0]
    for c in letters[1:]:
        if c.isupper() == current[-1].isupper():
            current += c
        else:
            groups.append(current)
            current = c
    groups.append(current)
    return groups

def smallest_repeating_unit(s):
    n = len(s)
    if n == 0:
        return ""
    for length in range(1, n):
        if n % length == 0:
            unit = s[:length]
            if unit * (n // length) == s:
                return unit
    return s

def is_repeated_pattern(s):
    n = len(s)
    if n == 0:
        return False
    for length in range(1, n):
        if n % length == 0:
            unit = s[:length]
            if unit * (n // length) == s:
                return True
    return False

def count_repeating_unit_repeats(s):
    n = len(s)
    if n == 0:
        return 0
    for length in range(1, n):
        if n % length == 0:
            unit = s[:length]
            if unit * (n // length) == s:
                return n // length
    return 1

def find_repeated_substrings_of_length(s, k):
    if k <= 0 or k > len(s):
        return []
    from collections import Counter
    subs = [s[i:i + k] for i in range(len(s) - k + 1)]
    counts = Counter(subs)
    seen = set()
    result = []
    for sub in subs:
        if counts[sub] > 1 and sub not in seen:
            result.append(sub)
            seen.add(sub)
    return result

def letter_to_number_sum(s):
    total = 0
    for c in s:
        if c.isalpha():
            total += ord(c.lower()) - ord('a') + 1
    return total

def shift_letters_by_position(s):
    result = []
    for i, c in enumerate(s):
        if c.isalpha():
            base = ord('A') if c.isupper() else ord('a')
            result.append(chr((ord(c) - base + i) % 26 + base))
        else:
            result.append(c)
    return "".join(result)

def is_each_letter_increasing(s):
    letters = [c.lower() for c in s if c.isalpha()]
    for i in range(1, len(letters)):
        if letters[i] <= letters[i - 1]:
            return False
    return True

def sum_of_letter_positions_per_word(s):
    result = []
    for word in s.split():
        total = sum(ord(c.lower()) - ord('a') + 1 for c in word if c.isalpha())
        result.append(total)
    return result

def make_acronym(phrase):
    letters = []
    for word in phrase.split():
        if word and word[0].isalpha():
            letters.append(word[0].upper())
    return "".join(letters)

def acronym_word_start_indices(s):
    if not s:
        return []
    indices = [0]
    for i, c in enumerate(s):
        if c == ' ' and i + 1 < len(s):
            indices.append(i + 1)
    return indices

def is_acronym_match(acronym, phrase):
    words = phrase.split()
    if len(words) != len(acronym):
        return False
    return all(w[0].lower() == a.lower() for w, a in zip(words, acronym))

def camel_case_acronym(s):
    if not s:
        return ""
    result = [s[0].upper()]
    for c in s[1:]:
        if c.isupper():
            result.append(c)
    return "".join(result)
